type defaultAttributesOption struct {
	metric.InstrumentOption
	keys []attribute.Key
}

// Experimental prevents the API from panicking when the option is used.
func (defaultAttributesOption) Experimental() {}

// AllowedKeys returns the attribute keys allowed by default for the
// instrument.
func (o defaultAttributesOption) AllowedKeys() []attribute.Key {
	return o.keys
}

// WithDefaultAttributes returns a metric.InstrumentOption that specifies which
// attribute keys are allowed by default for a metric instrument.
//
// When the returned option is passed during instrument creation, only
// attributes whose keys appear in keys are included in recorded data points.
// Passing no keys results in all attributes being filtered out (an empty
// attribute set). When the option is not provided, no filtering occurs.
//
// Attributes filtered out by default can be re-enabled by using the
// AttributeFilter of a View that matches the instrument in
// go.opentelemetry.io/otel/sdk/metric.
//
// This is an experimental option and may be changed in backwards-incompatible
// ways, or removed entirely, in a future release.
func WithDefaultAttributes(keys ...attribute.Key) metric.InstrumentOption {
	return defaultAttributesOption{keys: keys}
}
