package metric

import (
	"context"
	"testing"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric/x"
	"go.opentelemetry.io/otel/sdk/metric/metricdata"
)

func collectAttrs(t *testing.T, opts []Option, record func(context.Context, metric.Meter)) []attribute.Set {
	t.Helper()
	rdr := NewManualReader()
	all := append([]Option{WithReader(rdr)}, opts...)
	mp := NewMeterProvider(all...)
	record(context.Background(), mp.Meter("scratch"))
	var rm metricdata.ResourceMetrics
	if err := rdr.Collect(context.Background(), &rm); err != nil {
		t.Fatal(err)
	}
	var sets []attribute.Set
	for _, sm := range rm.ScopeMetrics {
		for _, m := range sm.Metrics {
			if sum, ok := m.Data.(metricdata.Sum[int64]); ok {
				for _, dp := range sum.DataPoints {
					sets = append(sets, dp.Attributes)
				}
			}
		}
	}
	return sets
}

func TestScratchDefaultAttributes(t *testing.T) {
	attrs := attribute.NewSet(attribute.String("a", "1"), attribute.String("b", "2"))

	// Filter to only key "a".
	sets := collectAttrs(t, nil, func(ctx context.Context, m metric.Meter) {
		c, _ := m.Int64Counter("f", x.WithDefaultAttributes(attribute.Key("a")))
		c.Add(ctx, 1, metric.WithAttributeSet(attrs))
	})
	if len(sets) != 1 || sets[0].Len() != 1 {
		t.Fatalf("filter: got %v", sets)
	}
	if v, _ := sets[0].Value("a"); v.AsString() != "1" {
		t.Fatalf("filter: expected a=1, got %v", sets[0].Encoded(attribute.DefaultEncoder()))
	}

	// Empty keys -> empty set.
	sets = collectAttrs(t, nil, func(ctx context.Context, m metric.Meter) {
		c, _ := m.Int64Counter("e", x.WithDefaultAttributes())
		c.Add(ctx, 1, metric.WithAttributeSet(attrs))
	})
	if len(sets) != 1 || sets[0].Len() != 0 {
		t.Fatalf("empty: expected empty set, got %v", sets)
	}

	// Not passed -> all retained.
	sets = collectAttrs(t, nil, func(ctx context.Context, m metric.Meter) {
		c, _ := m.Int64Counter("n")
		c.Add(ctx, 1, metric.WithAttributeSet(attrs))
	})
	if len(sets) != 1 || sets[0].Len() != 2 {
		t.Fatalf("none: expected 2 attrs, got %v", sets)
	}

	// View overrides per-instrument filtering (full attrs).
	view := NewView(Instrument{Name: "*"}, Stream{})
	sets = collectAttrs(t, []Option{WithView(view)}, func(ctx context.Context, m metric.Meter) {
		c, _ := m.Int64Counter("v", x.WithDefaultAttributes(attribute.Key("a")))
		c.Add(ctx, 1, metric.WithAttributeSet(attrs))
	})
	if len(sets) != 1 || sets[0].Len() != 2 {
		t.Fatalf("view: expected 2 attrs (override), got %v", sets)
	}
}
